    INSERT INTO "Question" ("id", "assessmentId", "textEn", "textFr", "order", "points", "setNumber") VALUES
      ('75b6f38c-8b18-4356-8ff6-ba17feacec7e', a_id, $bp$What does the Series Foreword name as the crisis in the Body of Christ?$bp$, $bp$Que nomme l'Avant-propos de la série comme la crise du Corps de Christ ?$bp$, 0, 1, 1),
      ('941f97f5-26de-48d4-8210-e8ee408a38bd', a_id, $bp$In the Introduction, a man inherits a vast estate yet lives in a roadside tent. Why?$bp$, $bp$Dans l'Introduction, un homme hérite d'un vaste domaine mais vit sous une tente au bord de la route. Pourquoi ?$bp$, 1, 1, 1),
      ('a203a138-8a5d-45cb-a815-b3d585d10cd5', a_id, $bp$According to Chapter One, what does a believer's poverty reveal?$bp$, $bp$Selon le chapitre un, que révèle la pauvreté d'un croyant ?$bp$, 2, 1, 1),
      ('e34ed6f2-fac3-44b9-a37d-e9d7ea743f03', a_id, $bp$What does the book say about the Midianites in the story of Gideon?$bp$, $bp$Que dit le livre des Madianites dans l'histoire de Gédéon ?$bp$, 3, 1, 1),
      ('ac360ef3-bc07-4d9e-92f2-c7cdbe46e586', a_id, $bp$What does the book's electricity illustration teach?$bp$, $bp$Qu'enseigne l'illustration de l'électricité dans le livre ?$bp$, 4, 1, 1),
      ('0ad61b93-8535-41f2-9b6c-3aabc1bb8bdc', a_id, $bp$What are the two errors named at the start of Chapter Two?$bp$, $bp$Quelles sont les deux erreurs nommées au début du chapitre deux ?$bp$, 5, 1, 1),
      ('0d4f3638-5d71-4931-98ee-8c979fc42a60', a_id, $bp$What does the Greek word prosagoge, translated access, describe?$bp$, $bp$Que décrit le mot grec prosagogè, traduit par accès ?$bp$, 6, 1, 1),
      ('98d6feb0-3401-4ead-b950-cb05cde03d47', a_id, $bp$In the widow's oil story, what limited the amount of oil she received?$bp$, $bp$Dans l'histoire de l'huile de la veuve, qu'est-ce qui limitait la quantité d'huile qu'elle recevait ?$bp$, 7, 1, 1),
      ('a0194fc8-59f8-411d-8bc4-fcfdac71bc68', a_id, $bp$In the story of Amos Striking, what was found after his death?$bp$, $bp$Dans l'histoire d'Amos Striking, qu'a-t-on trouvé après sa mort ?$bp$, 8, 1, 1),
      ('0be45dea-3251-4634-89c2-7e3071e0fa21', a_id, $bp$What does the name Lo Debar, where Mephibosheth lived, mean?$bp$, $bp$Que signifie le nom Lo-Debar, où vivait Mephibosheth ?$bp$, 9, 1, 1),
      ('40054351-d5cc-4eca-9fd5-a8373bd0abef', a_id, $bp$What cost the ten spies and their generation the land God had promised?$bp$, $bp$Qu'est-ce qui a coûté aux dix espions et à leur génération le pays que Dieu avait promis ?$bp$, 10, 1, 1),
      ('4b878476-b28e-48e8-bd3f-8fff2f912c55', a_id, $bp$What are the three dimensions of Kingdom systems taught in Chapter Four?$bp$, $bp$Quelles sont les trois dimensions des systèmes du Royaume enseignées au chapitre quatre ?$bp$, 11, 1, 1),
      ('b7c07acc-bc03-45bc-8735-9e5000d68df6', a_id, $bp$What happened to the ten lepers as they obeyed Jesus and went to the priests?$bp$, $bp$Qu'est-il arrivé aux dix lépreux quand ils ont obéi à Jésus et sont allés vers les prêtres ?$bp$, 12, 1, 1),
      ('53eb2d5d-f568-4a16-8772-226ee9b8f5b9', a_id, $bp$Before David killed Goliath, what had he already done, according to the book?$bp$, $bp$Avant de tuer Goliath, qu'avait déjà fait David, selon le livre ?$bp$, 13, 1, 1),
      ('62e7bd5b-23be-468d-b2f0-23e5c05604ba', a_id, $bp$According to Chapter Five, what did a key symbolise in the ancient world?$bp$, $bp$Selon le chapitre cinq, que symbolisait une clé dans le monde antique ?$bp$, 14, 1, 1),
      ('897b9659-7943-408c-a109-3b25a9d12204', a_id, $bp$What are the three elements in the book's definition of a Kingdom Key?$bp$, $bp$Quels sont les trois éléments de la définition d'une clé du Royaume dans le livre ?$bp$, 15, 1, 1),
      ('345570b0-0c99-4d17-bf9f-3229756ccf47', a_id, $bp$Psalm 103:7 says God made known His acts to Israel but His ways to Moses. What does the book say this shows?$bp$, $bp$Le Psaume 103.7 dit que Dieu a fait connaître ses actes à Israël mais ses voies à Moïse. Que dit le livre que cela montre ?$bp$, 16, 1, 1),
      ('69682f06-ddb4-4ac7-a2bc-fcb0006fa3ec', a_id, $bp$What does the Greek word exousia, used in John 1:12, mean?$bp$, $bp$Que signifie le mot grec exousia, utilisé en Jean 1.12 ?$bp$, 17, 1, 1),
      ('7eae050b-03da-4b07-8819-18a626b5abe0', a_id, $bp$What do the sons of Sceva teach about Kingdom Keys?$bp$, $bp$Qu'enseignent les fils de Scéva sur les clés du Royaume ?$bp$, 18, 1, 1),
      ('2f3afb67-4937-4b3a-b4e2-dd14d825d40d', a_id, $bp$Why did Zacchaeus give half his goods to the poor and restore fourfold?$bp$, $bp$Pourquoi Zachée a-t-il donné la moitié de ses biens aux pauvres et restitué au quadruple ?$bp$, 19, 1, 1),
      ('f0fd4fd1-f199-4490-9208-8a3c788d534f', a_id, $bp$The book teaches that a Kingdom citizen's poverty shows that God has not provided enough.$bp$, $bp$Le livre enseigne que la pauvreté d'un citoyen du Royaume montre que Dieu n'a pas assez pourvu.$bp$, 20, 1, 1),
      ('567afb1f-b50a-4358-b9e4-a3c5b78e9570', a_id, $bp$The book teaches that the finished work of Christ removed the need for faith, prayer, and the Word.$bp$, $bp$Le livre enseigne que l'œuvre achevée de Christ a supprimé le besoin de la foi, de la prière et de la Parole.$bp$, 21, 1, 1),
      ('7f5de190-c703-4f90-b717-e01ba9b5b709', a_id, $bp$According to the book, Amos Striking lived and died poor while standing on coal deposits he never knew about.$bp$, $bp$Selon le livre, Amos Striking a vécu et est mort pauvre en se tenant sur des gisements de charbon dont il ignorait l'existence.$bp$, 22, 1, 1),
      ('02b3fc1a-61b1-487f-b003-d2dfa0c7bc39', a_id, $bp$The book teaches that Jesus gave the keys of the Kingdom as a reward for spiritual performance.$bp$, $bp$Le livre enseigne que Jésus a donné les clés du Royaume comme récompense pour une performance spirituelle.$bp$, 23, 1, 1),
      ('117b91e2-ac42-417a-a828-82a4384cefc3', a_id, $bp$The book teaches that the new birth is the key that must be turned before any other key can function.$bp$, $bp$Le livre enseigne que la nouvelle naissance est la clé qui doit être tournée avant que toute autre clé puisse fonctionner.$bp$, 24, 1, 1);
    INSERT INTO "Option" ("id", "questionId", "textEn", "textFr", "isCorrect", "order") VALUES
      ('3263ea93-2e91-4c5e-9643-6ae28d6c9146', '75b6f38c-8b18-4356-8ff6-ba17feacec7e', $bp$The gap between what Christians believe about Heaven and what they know about the Bible$bp$, $bp$L'écart entre ce que les chrétiens croient du Ciel et ce qu'ils savent de la Bible$bp$, FALSE, 0),
      ('0467138c-572d-41d4-b2dd-8cffd120c1e5', '75b6f38c-8b18-4356-8ff6-ba17feacec7e', $bp$The gap between what leaders promise from the pulpit and what members can afford to give$bp$, $bp$L'écart entre ce que les dirigeants promettent depuis la chaire et ce que les membres peuvent se permettre de donner$bp$, FALSE, 1),
      ('31e37948-447f-4d0a-9a70-215c76f8237f', '75b6f38c-8b18-4356-8ff6-ba17feacec7e', $bp$The gap between what churches teach about salvation and what believers actually accept$bp$, $bp$L'écart entre ce que les églises enseignent du salut et ce que les croyants acceptent réellement$bp$, FALSE, 2),
      ('ec615fd3-7fd1-4065-bf13-03f8b860382a', '75b6f38c-8b18-4356-8ff6-ba17feacec7e', $bp$The gap between what believers legally possess and what they visibly experience$bp$, $bp$L'écart entre ce que les croyants possèdent légalement et ce qu'ils vivent visiblement$bp$, TRUE, 3),
      ('c54a50f8-044f-4cc9-9423-8479ec564f20', '941f97f5-26de-48d4-8210-e8ee408a38bd', $bp$His father's estate was taken by creditors before he could claim any part of it$bp$, $bp$Le domaine de son père a été saisi par des créanciers avant qu'il puisse en réclamer la moindre partie$bp$, FALSE, 0),
      ('6721ee48-c04b-4f91-8bf0-7d66d4876a3b', '941f97f5-26de-48d4-8210-e8ee408a38bd', $bp$He had not worked long enough to prove that he deserved what his father left$bp$, $bp$Il n'avait pas travaillé assez longtemps pour prouver qu'il méritait ce que son père lui avait laissé$bp$, FALSE, 1),
      ('80c37522-35e2-44e1-92e9-1793be0ff179', '941f97f5-26de-48d4-8210-e8ee408a38bd', $bp$The estate was too far away, and he could not afford the journey to reach it$bp$, $bp$Le domaine était trop loin, et il ne pouvait pas se payer le voyage pour y arriver$bp$, FALSE, 2),
      ('cec8f877-e35b-4c26-abbb-93de220f4cff', '941f97f5-26de-48d4-8210-e8ee408a38bd', $bp$No one ever told him how to access the inheritance that already belonged to him$bp$, $bp$Personne ne lui a jamais dit comment accéder à l'héritage qui lui appartenait déjà$bp$, TRUE, 3),
      ('a6ac763b-459d-4619-8067-75d84af71026', 'a203a138-8a5d-45cb-a815-b3d585d10cd5', $bp$A sign that God is testing the believer, and will end it once the lesson is learned$bp$, $bp$Un signe que Dieu met le croyant à l'épreuve, et qu'il y mettra fin une fois la leçon apprise$bp$, FALSE, 0),
      ('84d3f825-27ff-45e4-9ecd-71647b1d77af', 'a203a138-8a5d-45cb-a815-b3d585d10cd5', $bp$The gap between what was provided and what was accessed, never a lack on God's side$bp$, $bp$L'écart entre ce qui a été fourni et ce qui a été atteint, jamais un manque du côté de Dieu$bp$, TRUE, 1),
      ('c9401ac9-ac13-460e-982a-6bef2f5ae035', 'a203a138-8a5d-45cb-a815-b3d585d10cd5', $bp$A lack in what God has provided, which He will supply when the believer prays enough$bp$, $bp$Un manque dans ce que Dieu a fourni, qu'il comblera quand le croyant aura assez prié$bp$, FALSE, 2),
      ('69deb13e-4283-463b-a0c0-f81928588751', 'a203a138-8a5d-45cb-a815-b3d585d10cd5', $bp$A judgment for past sins, which must be confessed before any provision will come$bp$, $bp$Un jugement pour des péchés passés, qui doivent être confessés avant que toute provision vienne$bp$, FALSE, 3),
      ('7424bb36-aa06-4d56-a551-adef5c78e01b', 'e34ed6f2-fac3-44b9-a37d-e9d7ea743f03', $bp$They did not create the gap; they only exploited Gideon's lack of knowing who he was$bp$, $bp$Ils n'ont pas créé l'écart ; ils n'ont fait qu'exploiter le fait que Gédéon ne savait pas qui il était$bp$, TRUE, 0),
      ('3a082af9-88a9-40c0-a7b1-55250f0bb0a1', 'e34ed6f2-fac3-44b9-a37d-e9d7ea743f03', $bp$They were too strong to defeat, so Gideon could only hide until God removed them$bp$, $bp$Ils étaient trop forts pour être vaincus, donc Gédéon ne pouvait que se cacher jusqu'à ce que Dieu les retire$bp$, FALSE, 1),
      ('e8ced0b3-b41d-4e27-a0bb-86d68963d03e', 'e34ed6f2-fac3-44b9-a37d-e9d7ea743f03', $bp$They were sent by God to punish Gideon himself, until he repented of his own sin$bp$, $bp$Ils ont été envoyés par Dieu pour punir Gédéon lui-même, jusqu'à ce qu'il se repente de son propre péché$bp$, FALSE, 2),
      ('129cd2f0-d086-4343-abef-36617d4a573a', 'e34ed6f2-fac3-44b9-a37d-e9d7ea743f03', $bp$They created the gap by cursing Israel, so Gideon first had to break the curse in prayer$bp$, $bp$Ils ont créé l'écart en maudissant Israël, donc Gédéon devait d'abord briser la malédiction par la prière$bp$, FALSE, 3),
      ('29437da7-6a9b-48eb-91d5-bf8385a1b27f', 'ac360ef3-bc07-4d9e-92f2-c7cdbe46e586', $bp$Light comes on by itself in every house once electricity has been brought into the city$bp$, $bp$La lumière s'allume d'elle-même dans toutes les maisons une fois que l'électricité a été amenée dans la ville$bp$, FALSE, 0),
      ('2b0da5ae-bcb9-404d-afa9-af79d0619305', 'ac360ef3-bc07-4d9e-92f2-c7cdbe46e586', $bp$Wiring is the hardest part, so the owner must wait for experts to switch on the power$bp$, $bp$Le câblage est la partie la plus difficile, donc le propriétaire doit attendre que des experts mettent le courant$bp$, FALSE, 1),
      ('dd9bd2ba-0434-4f13-b395-bc0d28532cb7', 'ac360ef3-bc07-4d9e-92f2-c7cdbe46e586', $bp$Power may run through the wires, but light comes only when the citizen engages the system$bp$, $bp$Le courant peut passer dans les fils, mais la lumière ne vient que lorsque le citoyen actionne le système$bp$, TRUE, 2),
      ('95da894c-af8f-49ce-83cd-7688e60a514f', 'ac360ef3-bc07-4d9e-92f2-c7cdbe46e586', $bp$Power is given only to cities that have earned it through years of faithful public service$bp$, $bp$Le courant n'est donné qu'aux villes qui l'ont mérité par des années de service public fidèle$bp$, FALSE, 3),
      ('2c85cb45-a023-4960-abe8-b91b536a3bb8', '0ad61b93-8535-41f2-9b6c-3aabc1bb8bdc', $bp$That the believer has nothing to do because Christ did it all, and that he must strive to earn it$bp$, $bp$Que le croyant n'a rien à faire parce que Christ a tout fait, et qu'il doit s'efforcer de le mériter$bp$, TRUE, 0),
      ('16121269-f483-4da3-b751-108bd0fffaf2', '0ad61b93-8535-41f2-9b6c-3aabc1bb8bdc', $bp$That the Cross covers only sin and not sickness, and that it covers sickness but not sin$bp$, $bp$Que la Croix ne couvre que le péché et non la maladie, et qu'elle couvre la maladie mais non le péché$bp$, FALSE, 1),
      ('de70590a-65ed-45df-8067-f864cbd9b61e', '0ad61b93-8535-41f2-9b6c-3aabc1bb8bdc', $bp$That prayer should be silent and private always, and that prayer should be loud and public always$bp$, $bp$Que la prière doit toujours être silencieuse et privée, et qu'elle doit toujours être bruyante et publique$bp$, FALSE, 2),
      ('ed0201c3-815e-42a4-9898-7f810df3ed81', '0ad61b93-8535-41f2-9b6c-3aabc1bb8bdc', $bp$That Old Testament saints were saved by works, and that today's saints are saved by grace$bp$, $bp$Que les saints de l'Ancien Testament étaient sauvés par les œuvres, et ceux d'aujourd'hui par la grâce$bp$, FALSE, 3),
      ('572c0dfd-6afa-437e-a55f-844292d9a6e1', '0d4f3638-5d71-4931-98ee-8c979fc42a60', $bp$The right of a citizen to vote in a council after he has proved loyalty to the king$bp$, $bp$Le droit d'un citoyen de voter dans un conseil après avoir prouvé sa loyauté au roi$bp$, FALSE, 0),
      ('a295bed2-31c5-4301-b81a-643879d59f27', '0d4f3638-5d71-4931-98ee-8c979fc42a60', $bp$The right of a visitor to wait at the palace gate until the king agrees to see him$bp$, $bp$Le droit d'un visiteur d'attendre à la porte du palais jusqu'à ce que le roi accepte de le recevoir$bp$, FALSE, 1),
      ('c81a76b5-0a21-4350-addd-db8ea1de2e7b', '0d4f3638-5d71-4931-98ee-8c979fc42a60', $bp$The right of a person to be brought into the presence of a king, with permanent entry$bp$, $bp$Le droit d'une personne d'être amenée en présence d'un roi, avec une entrée permanente$bp$, TRUE, 2),
      ('90857497-dd83-4a88-95c1-7132a21382db', '0d4f3638-5d71-4931-98ee-8c979fc42a60', $bp$The right of a servant to receive daily wages from his master once his work is done$bp$, $bp$Le droit d'un serviteur de recevoir un salaire quotidien de son maître une fois son travail fait$bp$, FALSE, 3),
      ('2df2d836-441a-454e-818e-36f7f6f9b497', '98d6feb0-3401-4ead-b950-cb05cde03d47', $bp$The amount of faith the prophet Elisha had at the time, not the widow's own effort$bp$, $bp$La quantité de foi qu'avait le prophète Élisée à ce moment-là, et non l'effort de la veuve$bp$, FALSE, 0),
      ('fa851317-89fa-428f-af71-dfca22ecf4fb', '98d6feb0-3401-4ead-b950-cb05cde03d47', $bp$The size of the single jar she began with, which could only be filled so many times$bp$, $bp$La taille de l'unique cruche avec laquelle elle avait commencé, qui ne pouvait être remplie que quelques fois$bp$, FALSE, 1),
      ('aad3c206-b91f-4a58-9814-eecedf54a35f', '98d6feb0-3401-4ead-b950-cb05cde03d47', $bp$The number of vessels she gathered and prepared to receive it, not God's power$bp$, $bp$Le nombre de vases qu'elle avait rassemblés et préparés pour la recevoir, et non la puissance de Dieu$bp$, TRUE, 2),
      ('09735d4e-bb5d-495f-8082-21c6b79b62e4', '98d6feb0-3401-4ead-b950-cb05cde03d47', $bp$The number of neighbours who agreed to lend her their own oil to pour out$bp$, $bp$Le nombre de voisins qui ont accepté de lui prêter leur propre huile à verser$bp$, FALSE, 3),
      ('3350c4e6-3db8-4c1d-9e1d-d50cc5fe15c2', 'a0194fc8-59f8-411d-8bc4-fcfdac71bc68', $bp$A deed to a second farm, which the county had kept hidden from him for many years$bp$, $bp$Un acte de propriété d'une seconde ferme, que le comté lui avait caché pendant de nombreuses années$bp$, FALSE, 0),
      ('359aaee2-4128-4a41-82af-51059304dcb4', 'a0194fc8-59f8-411d-8bc4-fcfdac71bc68', $bp$A hidden will from his father, which left him the farm and all the money in the bank$bp$, $bp$Un testament caché de son père, qui lui laissait la ferme et tout l'argent de la banque$bp$, FALSE, 1),
      ('1a6aab3c-b66f-4962-9aea-96d910c20bad', 'a0194fc8-59f8-411d-8bc4-fcfdac71bc68', $bp$Coal deposits under his farm, later sold for millions, which he never knew were there$bp$, $bp$Des gisements de charbon sous sa ferme, vendus plus tard des millions, dont il n'avait jamais su l'existence$bp$, TRUE, 2),
      ('f67cbab9-7373-4d98-9467-a67cf64c1d33', 'a0194fc8-59f8-411d-8bc4-fcfdac71bc68', $bp$Gold coins buried near his house, which his children had searched for during his life$bp$, $bp$Des pièces d'or enterrées près de sa maison, que ses enfants avaient cherchées de son vivant$bp$, FALSE, 3),
      ('6bc8eccd-44cb-4174-999c-06be46394d5b', '0be45dea-3251-4634-89c2-7e3071e0fa21', $bp$A place of exile: a distant land where the royal family was sent when the king fell$bp$, $bp$Un lieu d'exil : une terre lointaine où la famille royale était envoyée quand le roi tombait$bp$, FALSE, 0),
      ('793b9212-a6e8-45c1-9955-642f3ba1a2f2', '0be45dea-3251-4634-89c2-7e3071e0fa21', $bp$A place of no pasture: a barren place, a wasteland, a place of nothing$bp$, $bp$Un lieu sans pâturage : un endroit stérile, un désert, un lieu de rien$bp$, TRUE, 1),
      ('ef9d1bde-df83-4bf9-b5cb-fcd4ea8d2688', '0be45dea-3251-4634-89c2-7e3071e0fa21', $bp$A place of hiding: a cave in the hills, a secret refuge, a place of safety$bp$, $bp$Un lieu de cachette : une grotte dans les collines, un refuge secret, un lieu de sécurité$bp$, FALSE, 2),
      ('3f5404e3-0cfb-4bef-8c3f-6abb9b24aaed', '0be45dea-3251-4634-89c2-7e3071e0fa21', $bp$A place of no water: a dry well, a desert road, a place of great thirst$bp$, $bp$Un lieu sans eau : un puits à sec, une route du désert, un lieu de grande soif$bp$, FALSE, 3),
      ('bb750168-08e4-4ef8-bdbf-98083d4a9795', '40054351-d5cc-4eca-9fd5-a8373bd0abef', $bp$Their lack of a leader: Moses had died, and no one else would lead them into the land of Canaan$bp$, $bp$Leur manque de chef : Moïse était mort, et personne d'autre ne les conduirait dans le pays de Canaan$bp$, FALSE, 0),
      ('af256e39-d2b7-4b48-a6f0-beef9621ba23', '40054351-d5cc-4eca-9fd5-a8373bd0abef', $bp$Their lack of weapons: they had no army large enough to fight the giants who lived in the land$bp$, $bp$Leur manque d'armes : ils n'avaient pas d'armée assez grande pour combattre les géants qui vivaient dans le pays$bp$, FALSE, 1),
      ('33dedc3c-f120-4ae3-8450-70ae0c6e95c6', '40054351-d5cc-4eca-9fd5-a8373bd0abef', $bp$Their ignorance of their authority: they saw themselves as grasshoppers and did not take it$bp$, $bp$Leur ignorance de leur autorité : ils se voyaient comme des sauterelles et ne l'ont pas prise$bp$, TRUE, 2),
      ('4229bc70-59cb-42dc-a764-de37130dc214', '40054351-d5cc-4eca-9fd5-a8373bd0abef', $bp$Their lack of a promise: God had not told them clearly that the land was really theirs to take$bp$, $bp$Leur manque de promesse : Dieu ne leur avait pas dit clairement que le pays était vraiment à eux pour le prendre$bp$, FALSE, 3),
      ('4458a5ba-06ba-49ff-a411-80a1d99a3196', '4b878476-b28e-48e8-bd3f-8fff2f912c55', $bp$Kingdom faith, Kingdom hope, and Kingdom love$bp$, $bp$La foi du Royaume, l'espérance du Royaume et l'amour du Royaume$bp$, FALSE, 0),
      ('e7da93f2-0fa2-41df-b28c-b2d714fbb437', '4b878476-b28e-48e8-bd3f-8fff2f912c55', $bp$Kingdom signs, Kingdom wonders, and Kingdom gifts$bp$, $bp$Les signes du Royaume, les prodiges du Royaume et les dons du Royaume$bp$, FALSE, 1),
      ('cf9a0701-ccb1-4668-97a1-049c8945281b', '4b878476-b28e-48e8-bd3f-8fff2f912c55', $bp$Kingdom laws, Kingdom protocols, and Kingdom order$bp$, $bp$Les lois du Royaume, les protocoles du Royaume et l'ordre du Royaume$bp$, TRUE, 2),
      ('797fc27c-46ff-4cd5-b6ab-477d03528e65', '4b878476-b28e-48e8-bd3f-8fff2f912c55', $bp$Kingdom prayer, Kingdom giving, and Kingdom fasting$bp$, $bp$La prière du Royaume, le don du Royaume et le jeûne du Royaume$bp$, FALSE, 3),
      ('e270f536-c764-424c-a382-8d009cff7ef6', 'b7c07acc-bc03-45bc-8735-9e5000d68df6', $bp$They were cleansed as they went, showing that the protocol required obedience$bp$, $bp$Ils ont été purifiés en chemin, ce qui montre que le protocole exigeait l'obéissance$bp$, TRUE, 0),
      ('71e904e6-1e00-4c00-8431-d580bebccc6a', 'b7c07acc-bc03-45bc-8735-9e5000d68df6', $bp$They were cleansed when they reached the priests, who prayed over them at the temple$bp$, $bp$Ils ont été purifiés en arrivant chez les prêtres, qui ont prié sur eux au temple$bp$, FALSE, 1),
      ('3ee1cbfd-454c-411a-886b-a7a0106173e2', 'b7c07acc-bc03-45bc-8735-9e5000d68df6', $bp$They were cleansed before they left, and went to the priests only to give thanks$bp$, $bp$Ils ont été purifiés avant de partir, et ne sont allés vers les prêtres que pour rendre grâce$bp$, FALSE, 2),
      ('c22da3a3-a730-4643-a4ae-97d4d2c896ff', 'b7c07acc-bc03-45bc-8735-9e5000d68df6', $bp$They were cleansed when Jesus touched them, as He had done for others before them$bp$, $bp$Ils ont été purifiés quand Jésus les a touchés, comme il l'avait fait pour d'autres avant eux$bp$, FALSE, 3),
      ('e7e46c0f-ccd8-43bc-bc49-4e6fd642a130', '53eb2d5d-f568-4a16-8772-226ee9b8f5b9', $bp$Killed a lion and a bear in his father's fields: a private victory before the public one$bp$, $bp$Tué un lion et un ours dans les champs de son père : une victoire privée avant la victoire publique$bp$, TRUE, 0),
      ('d1999b4d-f3dc-464a-8b95-04f4ff75d5c9', '53eb2d5d-f568-4a16-8772-226ee9b8f5b9', $bp$Been anointed by Samuel before his brothers: a prophetic sign before the battle$bp$, $bp$Été oint par Samuel devant ses frères : un signe prophétique avant la bataille$bp$, FALSE, 1),
      ('f301b6d2-69a4-4c81-9127-2b87821b5dbd', '53eb2d5d-f568-4a16-8772-226ee9b8f5b9', $bp$Defeated a Philistine scout in a small fight: a first test before the main battle$bp$, $bp$Vaincu un éclaireur philistin dans un petit combat : une première épreuve avant la grande bataille$bp$, FALSE, 2),
      ('c6b8e991-4eb3-4c1b-80ed-7776fef6e68b', '53eb2d5d-f568-4a16-8772-226ee9b8f5b9', $bp$Fasted for forty days in the wilderness: a private discipline before the public battle$bp$, $bp$Jeûné quarante jours dans le désert : une discipline privée avant la bataille publique$bp$, FALSE, 3),
      ('76349e2b-17dc-4862-9998-94611633a12e', '62e7bd5b-23be-468d-b2f0-23e5c05604ba', $bp$Safety, secrecy, and privacy: the emblem of a locked family home and its goods$bp$, $bp$La sécurité, le secret et l'intimité : l'emblème d'une maison familiale fermée à clé et de ses biens$bp$, FALSE, 0),
      ('feb8cba5-b112-4d5c-b55a-3d47c5309e5c', '62e7bd5b-23be-468d-b2f0-23e5c05604ba', $bp$Wealth, status, and honour: the emblem of a rich man and his large household$bp$, $bp$La richesse, le statut et l'honneur : l'emblème d'un homme riche et de sa grande maisonnée$bp$, FALSE, 1),
      ('8731408a-8338-4a98-9819-936edfc08dcf', '62e7bd5b-23be-468d-b2f0-23e5c05604ba', $bp$Authority, responsibility, and trust: the emblem of delegated dominion$bp$, $bp$L'autorité, la responsabilité et la confiance : l'emblème de la domination déléguée$bp$, TRUE, 2),
      ('1a76dfe2-fc0d-43a4-9bcc-db98e4814853', '62e7bd5b-23be-468d-b2f0-23e5c05604ba', $bp$Strength, courage, and victory: the emblem of a conquering army in the field$bp$, $bp$La force, le courage et la victoire : l'emblème d'une armée conquérante sur le terrain$bp$, FALSE, 3),
      ('f1c921e9-c558-41f7-a1b3-067cd8bf822f', '897b9659-7943-408c-a109-3b25a9d12204', $bp$It is ancient, it must be practised in secret and with fasting, and it has a general purpose$bp$, $bp$Elle est ancienne, elle doit être pratiquée en secret et par le jeûne, et elle a un but général$bp$, FALSE, 0),
      ('7205d209-9401-4728-8c16-9dccaabbf337', '897b9659-7943-408c-a109-3b25a9d12204', $bp$It is personal, it must be discovered by each believer alone, and it has a hidden meaning$bp$, $bp$Elle est personnelle, elle doit être découverte par chaque croyant seul, et elle a un sens caché$bp$, FALSE, 1),
      ('1b241220-a3ee-4861-80dc-168ab868bf1e', '897b9659-7943-408c-a109-3b25a9d12204', $bp$It is traditional, it must be taught by a church leader, and it has a fixed ritual$bp$, $bp$Elle est traditionnelle, elle doit être enseignée par un responsable d'Église, et elle a un rituel fixe$bp$, FALSE, 2),
      ('acf57377-14d9-4815-9c5c-b71e1e8e9dc9', '897b9659-7943-408c-a109-3b25a9d12204', $bp$It is biblical, it is applied with faith and intentionality, and it has a specific function$bp$, $bp$Elle est biblique, elle s'applique avec foi et intention, et elle a une fonction précise$bp$, TRUE, 3),
      ('0c8d6c72-4385-4b2b-91e1-0992c6972881', '345570b0-0c99-4d17-bf9f-3229756ccf47', $bp$Acts are what God judges, while ways are how He forgives; Israel was judged for lacking the law$bp$, $bp$Les actes sont ce que Dieu juge, les voies sont la manière dont il pardonne ; Israël a été jugé pour avoir manqué de loi$bp$, FALSE, 0),
      ('e8a99ba3-6f35-4911-99d6-c1c0d93370f4', '345570b0-0c99-4d17-bf9f-3229756ccf47', $bp$Acts are what God says, while ways are how He feels; Moses was closer to God because of his age$bp$, $bp$Les actes sont ce que Dieu dit, les voies sont ce qu'il ressent ; Moïse était plus proche de Dieu à cause de son âge$bp$, FALSE, 1),
      ('264c2a36-23e8-45b1-b3d4-27c015cde4af', '345570b0-0c99-4d17-bf9f-3229756ccf47', $bp$Acts are what God creates, while ways are where He lives; Moses alone could enter the tabernacle$bp$, $bp$Les actes sont ce que Dieu crée, les voies sont où il habite ; Moïse seul pouvait entrer dans le tabernacle$bp$, FALSE, 2),
